        { "Autorizacion:Asignaturas:2:Codigo", "B-203" },
        { "Autorizacion:Asignaturas:2:Codigo", "BD-203 " },
        { "Autorizacion:Asignaturas:2:Codigo", " BD-203" },
        { "Autorizacion:Asignaturas:2:Codigo", "BD 203" },
